"use client"

import * as React from "react"
import { motion, useMotionValue, useReducedMotion, useSpring } from "motion/react"

import { buildTrack, lengthAt, useRailRows, type RailTrack } from "@/components/ui/rail-path"
import { cn } from "@/lib/utils"

type ReadingRailItem = {
  /** matches the `id` of the heading it points to */
  id: string
  label: string
  /** Optional destination when the rail is used for page navigation. */
  href?: string
  /** indents the row, and bends the rail sideways to reach it; 0 is a top level heading */
  depth?: number
}

type ReadingRailProps = Omit<React.ComponentProps<"nav">, "children"> & {
  items: ReadingRailItem[]
  /** the element that scrolls; leave it out to follow the page */
  container?: HTMLElement | null
  /** how far below the top of the view a heading counts as reached, in px */
  offset?: number
  title?: string
  /** Controls the active item for route-based navigation instead of scroll tracking. */
  activeId?: string
}

const RAIL_X = 7
const STEP = 14

// a table of contents on a dashed rail that bends in where a heading is indented. a solid line fills
// the rail as you read, and a small ember at its tip turns with every bend
function ReadingRail({ items, container = null, offset = 24, title = "On this page", activeId, className, ...props }: ReadingRailProps) {
  const reduceMotion = useReducedMotion()
  const list = React.useRef<HTMLUListElement>(null)
  const base = React.useRef<SVGPathElement>(null)
  const trackRef = React.useRef<RailTrack | null>(null)
  const [current, setCurrent] = React.useState(0)
  const [percent, setPercent] = React.useState(0)
  const position = useMotionValue(0)

  const rows = useRailRows(list, RAIL_X, STEP, items)
  const track = React.useMemo(() => buildTrack(rows ?? []), [rows])

  // the fill, in px along the path. one spring drives the line and the ember together
  const reached = useSpring(0, reduceMotion ? { duration: 0 } : { stiffness: 200, damping: 30, mass: 0.7 })
  const fill = useMotionValue(0)
  const x = useMotionValue(RAIL_X)
  const y = useMotionValue(0)
  const angle = useMotionValue(0)

  React.useEffect(() => {
    trackRef.current = track
    const target = lengthAt(track, position.get())
    if (reduceMotion) reached.jump(target)
    else reached.set(target)
  }, [position, reduceMotion, reached, track])

  // keep the line and the ember on the path
  const place = React.useCallback(
    (length: number) => {
      const path = base.current
      const total = trackRef.current?.total ?? 0
      if (!path || !total) return
      fill.set(Math.min(length / total, 1))
      const here = path.getPointAtLength(Math.min(length, total))
      const ahead = path.getPointAtLength(Math.min(length + 1, total))
      const behind = path.getPointAtLength(Math.max(length - 1, 0))
      x.set(here.x)
      y.set(here.y)
      angle.set((Math.atan2(-(ahead.x - behind.x), ahead.y - behind.y) * 180) / Math.PI)
    },
    [angle, fill, x, y]
  )

  React.useEffect(() => reached.on("change", place), [place, reached])

  // when the rows are measured or move, put the ember back where the rail now is
  React.useEffect(() => place(reached.get()), [place, reached, track])

  React.useEffect(() => {
    let frame = 0
    const measure = () => {
      frame = 0
      if (activeId !== undefined) {
        const index = items.findIndex((item) => item.id === activeId)
        if (index < 0) { position.set(0); reached.jump(0); setCurrent(-1); setPercent(0); return }
        position.set(index)
        const length = lengthAt(trackRef.current ?? track, index)
        if (reduceMotion) reached.jump(length)
        else reached.set(length)
        setCurrent(index)
        setPercent(items.length > 1 ? Math.round(index / (items.length - 1) * 100) : 0)
        return
      }
      const top = container ? container.getBoundingClientRect().top : 0
      const line = top + offset
      const tops = items.map((item) => document.getElementById(item.id)?.getBoundingClientRect().top ?? Infinity)
      let index = -1
      tops.forEach((value, i) => {
        if (value <= line + 1) index = i
      })
      const scrollable = container
        ? container.scrollHeight - container.clientHeight
        : document.documentElement.scrollHeight - window.innerHeight
      const scrolled = container ? container.scrollTop : window.scrollY
      const atEnd = scrollable > 0 && scrolled >= scrollable - 2
      let next: number
      if (atEnd) next = items.length - 1
      else if (index < 0) next = 0
      else if (index >= items.length - 1) next = items.length - 1
      else {
        const span = tops[index + 1] - tops[index]
        next = index + (span > 0 ? Math.min(Math.max((line - tops[index]) / span, 0), 1) : 0)
      }
      position.set(next)
      const length = lengthAt(trackRef.current ?? track, next)
      if (reduceMotion) reached.jump(length)
      else reached.set(length)
      setCurrent(atEnd ? items.length - 1 : Math.max(index, 0))
      setPercent(scrollable > 0 ? Math.round(Math.min(Math.max(scrolled / scrollable, 0), 1) * 100) : 0)
    }
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(measure)
    }
    schedule()
    const scroller: HTMLElement | Window = container ?? window
    scroller.addEventListener("scroll", schedule, { passive: true })
    window.addEventListener("resize", schedule)
    return () => {
      cancelAnimationFrame(frame)
      scroller.removeEventListener("scroll", schedule)
      window.removeEventListener("resize", schedule)
    }
  }, [activeId, container, items, offset, position, reached, reduceMotion, track])

  function go(id: string) {
    const target = document.getElementById(id)
    if (!target) return
    const behavior = reduceMotion ? "auto" : "smooth"
    if (container) {
      const delta = target.getBoundingClientRect().top - (container.getBoundingClientRect().top + offset)
      container.scrollTo({ top: container.scrollTop + delta, behavior })
    } else {
      window.scrollTo({ top: window.scrollY + target.getBoundingClientRect().top - offset, behavior })
    }
  }

  return (
    <nav data-slot="reading-rail" aria-label={title} className={cn("relative", className)} {...props}>
      <div className="mb-3 flex items-baseline justify-between pl-7">
        <p className="text-[11px] font-medium tracking-[0.08em] text-foreground/45 uppercase">{title}</p>
        <p className="text-[11px] text-foreground/45 tabular-nums">{percent}%</p>
      </div>
      <ul ref={list} className="relative flex flex-col">
        {rows && track.d && (
          <svg aria-hidden className="pointer-events-none absolute top-0 left-0 h-full w-8 overflow-visible">
            <path ref={base} d={track.d} fill="none" strokeWidth="1.5" strokeLinecap="round" strokeDasharray="0.1 5" className="stroke-foreground/35" />
            <motion.path d={track.d} fill="none" strokeWidth="1.75" strokeLinecap="round" className="stroke-glow" style={{ pathLength: fill }} />
            {rows.map((row, index) => (
              <circle
                key={index}
                cx={row.x}
                cy={row.y}
                r={index === current ? 3.25 : 2.25}
                className={cn(index <= current ? "fill-glow" : "fill-background stroke-foreground/35", "transition-[r] duration-200")}
                strokeWidth="1.25"
              />
            ))}
            <motion.g style={{ x, y, rotate: angle, opacity: current < 0 ? 0 : 1 }}>
              <rect x="-2.5" y="-6.5" width="5" height="13" rx="2.5" className="fill-glow stroke-background" strokeWidth="2" paintOrder="stroke" />
            </motion.g>
          </svg>
        )}
        {items.map((item, index) => {
          const Element = item.href ? "a" : "button"
          return (
          <li key={item.id} data-rail-row data-depth={item.depth ?? 0} className="relative">
            <Element
              type={item.href ? undefined : "button"}
              href={item.href}
              onClick={item.href ? undefined : () => go(item.id)}
              aria-current={index === current ? "location" : undefined}
              className={cn(
                "flex min-h-8 w-full cursor-pointer items-center rounded-lg py-1.5 pr-2 text-left text-[13px] leading-snug outline-none transition-colors duration-150 focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-ring",
                index === current ? "font-medium text-foreground" : index < current ? "text-foreground/70 hover:text-foreground" : "text-foreground/45 hover:text-foreground"
              )}
              style={{ paddingLeft: 28 + (item.depth ?? 0) * STEP }}
            >
              {item.label}
            </Element>
          </li>
        )})}
      </ul>
    </nav>
  )
}

export { ReadingRail, type ReadingRailItem, type ReadingRailProps }

"use client"

import * as React from "react"

// the geometry that the rail components share: a path drawn through the centre of every row,
// stepping sideways with rounded elbows where a row is indented, and a short curved hook that
// turns off the rail into a row

type RailRow = { x: number; y: number }

type RailTrack = {
  /** the full path, from the first row to the last */
  d: string
  /** how far along the path each row sits, in px */
  at: number[]
  total: number
}

/** a path through every row. rows that sit at a different x get a rounded jog halfway between them */
function buildTrack(rows: RailRow[], radius = 7): RailTrack {
  if (!rows.length) return { d: "", at: [], total: 0 }
  let d = `M ${rows[0].x} ${rows[0].y}`
  let length = 0
  const at = [0]
  for (let i = 1; i < rows.length; i++) {
    const a = rows[i - 1]
    const b = rows[i]
    if (a.x === b.x) {
      d += ` V ${b.y}`
      length += b.y - a.y
    } else {
      const dir = b.x > a.x ? 1 : -1
      const dx = Math.abs(b.x - a.x)
      const r = Math.min(radius, dx / 2, (b.y - a.y) / 4)
      const mid = (a.y + b.y) / 2
      d += ` V ${mid - r} A ${r} ${r} 0 0 ${dir === 1 ? 0 : 1} ${a.x + dir * r} ${mid} H ${b.x - dir * r}`
      d += ` A ${r} ${r} 0 0 ${dir === 1 ? 1 : 0} ${b.x} ${mid + r} V ${b.y}`
      length += mid - r - a.y + (Math.PI * r) / 2 + (dx - 2 * r) + (Math.PI * r) / 2 + (b.y - mid - r)
    }
    at.push(length)
  }
  return { d, at, total: length }
}

/** how far along the track a position is, where 1.5 means halfway between the second and third row */
function lengthAt(track: RailTrack, position: number) {
  if (!track.at.length) return 0
  const clamped = Math.min(Math.max(position, 0), track.at.length - 1)
  const index = Math.min(Math.floor(clamped), track.at.length - 2)
  if (index < 0) return 0
  const t = clamped - index
  return track.at[index] + (track.at[index + 1] - track.at[index]) * t
}

/**
 * measures the centre of each `[data-rail-row]` inside the list. a row's `data-depth` shifts it
 * sideways by `step` px. returns null until the first measure, so nothing is drawn on the server
 */
function useRailRows(list: React.RefObject<HTMLElement | null>, x: number, step: number, watch: unknown) {
  const [rows, setRows] = React.useState<RailRow[] | null>(null)

  React.useEffect(() => {
    const node = list.current
    if (!node) return
    let frame = 0
    const measure = () => {
      frame = 0
      const found = Array.from(node.querySelectorAll<HTMLElement>("[data-rail-row]"))
      setRows(
        found.map((row) => ({
          x: x + Number(row.dataset.depth ?? 0) * step,
          y: row.offsetTop + row.offsetHeight / 2,
        }))
      )
    }
    const schedule = () => {
      if (!frame) frame = requestAnimationFrame(measure)
    }
    schedule()
    const observer = new ResizeObserver(schedule)
    observer.observe(node)
    node.querySelectorAll("[data-rail-row]").forEach((row) => observer.observe(row))
    return () => {
      cancelAnimationFrame(frame)
      observer.disconnect()
    }
  }, [list, x, step, watch])

  return rows
}

export { buildTrack, lengthAt, useRailRows, type RailRow, type RailTrack }

import type { CSSProperties } from "react"
import type { TargetAndTransition, Transition } from "motion/react"

// shared spring presets, every component picks from these
export const springs = {
  snappy: { stiffness: 520, damping: 34, mass: 0.6 },
  soft: { stiffness: 260, damping: 26, mass: 0.8 },
  glide: { stiffness: 120, damping: 20, mass: 1 },
} as const

export type SpringName = keyof typeof springs

export function spring(name: SpringName): Transition {
  return { type: "spring", ...springs[name] }
}

// how a glow fades once its source moves away: slow, with a long tail
export const afterglow = {
  linger: 0.9,
  ease: [0.22, 1, 0.36, 1],
} as const satisfies { linger: number; ease: Transition["ease"] }

// paints only the padding ring of an element, used for glowing borders
export const ringMask: CSSProperties = {
  WebkitMask:
    "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
  WebkitMaskComposite: "xor",
  mask: "linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0)",
  maskComposite: "exclude",
}

// small icon gestures, played when a control is pressed or selected
export const iconGestures = {
  pop: { scale: [1, 1.2, 1] },
  ring: { rotate: [0, -18, 14, -9, 4, 0], scale: [1, 1.12, 1] },
  // a gear looks the same after half a turn, so it can rest there and snap back unseen
  turn: { rotate: [0, 180], scale: [1, 1.12, 1] },
  hop: { y: [0, -3, 0], scale: [1, 1.1, 1] },
  nudge: { x: [0, 2.5, 0], scale: [1, 1.1, 1] },
} satisfies Record<string, TargetAndTransition>

export type IconGesture = keyof typeof iconGestures

// leaving a gesture is instant: every gesture already ends at, or looks like, its resting pose
export const iconRest: TargetAndTransition = { scale: 1, rotate: 0, x: 0, y: 0, transition: { duration: 0 } }
